  7	public class NotificationService {
  8	    private final MessageRepository messageRepository;
  9	    private final List<NotificationHandler> handlers = new ArrayList<>();
 10	
 11	    public NotificationService(MessageRepository messageRepository) {
 12	        this.messageRepository = messageRepository;
 13	        registerDefaultHandlers();
 14	    }
 15	
 16	    private void registerDefaultHandlers() {
 17	        handlers.add(new GuestConfirmationHandler(messageRepository));
 18	        handlers.add(new GovernanceConfirmationHandler(messageRepository));
 19	        handlers.add(new FinanceConfirmationHandler(messageRepository));
 20	        handlers.add(new GovernanceCancellationHandler(messageRepository));
 21	        handlers.add(new FinanceCancellationHandler(messageRepository));
 22	    }
 23	
 24	    public void notifyReservationConfirmed(Reservation reservation, RoomType roomType) {
 25	        for (NotificationHandler handler : handlers) {
 26	            if (handler.shouldHandle(ReservationEvent.CONFIRMED)) {
 27	                handler.handle(reservation, roomType, null);
 28	            }
 29	        }
 30	    }
 31	
 32	    public void notifyReservationCancelled(Reservation reservation, RoomType roomType, Double refundAmount) {
 33	        for (NotificationHandler handler : handlers) {
 34	            if (handler.shouldHandle(ReservationEvent.CANCELLED)) {
 35	                handler.handle(reservation, roomType, refundAmount);
 36	            }
 37	        }
 38	    }
 39	
 40	    public void registerHandler(NotificationHandler handler) {
 41	        handlers.add(handler);
 42	    }
 43	
 44	    interface NotificationHandler {
 45	        boolean shouldHandle(ReservationEvent event);
 46	        void handle(Reservation reservation, RoomType roomType, Double refundAmount);
 47	    }
 48	
 49	    enum ReservationEvent {
 50	        CONFIRMED, CANCELLED
 51	    }
 52	
 53	    static class GuestConfirmationHandler implements NotificationHandler {
 54	        private final MessageRepository messageRepository;
 55	
 56	        GuestConfirmationHandler(MessageRepository messageRepository) {
 57	            this.messageRepository = messageRepository;
 58	        }
 59	
 60	        @Override
 61	        public boolean shouldHandle(ReservationEvent event) {
 62	            return event == ReservationEvent.CONFIRMED;
 63	        }
 64	
 65	        @Override
 66	        public void handle(Reservation reservation, RoomType roomType, Double refundAmount) {
 67	            String document = formatDocument(reservation, roomType);
 68	            String body = """
 69	                    Olá, %s!
 70	
 71	                    Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:
 72	
 73	                    %s
 74	
 75	                    A entrada é a partir das 14h, e a saída, até as 12h.
 76	                    Até breve!
 77	                    """.formatted(reservation.getGuestName(), document);
 78	
 79	            messageRepository.save(new Message(
 80	                    0,
 81	                    MessageChannel.EMAIL,
 82	                    reservation.getGuestEmail(),
 83	                    "Reserva confirmada - Pousada Maré Alta",
 84	                    body
 85	            ));
 86	        }
 87	
 88	        private String formatDocument(Reservation reservation, RoomType roomType) {
 89	            String nightsText = reservation.getNights() == 1 ? "1 diária" : reservation.getNights() + " diárias";
 90	            String document = "Comprovante de reserva nº " + reservation.getId() + "\n" +
 91	                    "Hóspede: " + reservation.getGuestName() + " (CPF " + formatCpf(reservation.getGuestCpf()) + ")\n" +
 92	                    "Quarto: " + reservation.getRoomNumber() + " (" + roomType.getDisplayName() + ")\n" +
 93	                    "Entrada: " + DateUtil.format(reservation.getCheckIn()) + " | Saída: " + DateUtil.format(reservation.getCheckOut()) + " | " + nightsText + "\n" +
 94	                    "Diárias: R$ " + formatMoney(reservation.getSubtotal());
 95	            if (reservation.getDiscount() > 0) {
 96	                document += "\nDesconto: R$ " + formatMoney(reservation.getDiscount());
 97	            }
 98	            document += "\nTotal: R$ " + formatMoney(reservation.getTotal());
 99	            return document;
100	        }
101	
102	        private String formatCpf(String cpf) {
103	            if (cpf.length() == 11) {
104	                return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." + cpf.substring(6, 9) + "-" + cpf.substring(9);
105	            }
106	            return cpf;
107	        }
108	
109	        private String formatMoney(double amount) {
110	            return String.format("%.2f", amount).replace(".", ",");
111	        }
112	    }
