435	import br.com.pousada.marealta.api.*;
436	import br.com.pousada.marealta.service.*;
437	import io.javalin.Javalin;
438	
439	public class Main {
440	    public static void main(String[] args) {
441	        int port = getPort();
442	
443	        MessageRepository messageRepository = new MessageRepository();
444	        NotificationService notificationService = new NotificationService(messageRepository);
445	        ReservationService reservationService = new ReservationService(notificationService);
446	        ReportService reportService = new ReportService(reservationService);
447	
448	        Javalin app = Javalin.create().start(port);
449	
450	        ApiErrorHandler.register(app);
451	        RoomController.register(app, reservationService);
452	        ReservationController.register(app, reservationService);
453	        MessageController.register(app, messageRepository);
454	        ReportController.register(app, reportService);
455	
456	        System.out.println("Servidor iniciado na porta " + port);
457	    }
458	
459	    private static int getPort() {
460	        String portEnv = System.getenv("PORT");
461	        if (portEnv != null && !portEnv.isEmpty()) {
462	            try {
463	                return Integer.parseInt(portEnv);
464	            } catch (NumberFormatException e) {
465	                return 7070;
466	            }
467	        }
468	        return 7070;
469	    }
470	}
471	package br.com.pousada.marealta.service;
472	
473	import br.com.pousada.marealta.model.Message;
474	import java.util.*;
475	import java.util.concurrent.ConcurrentHashMap;
476	
477	public class MessageRepository {
478	    private final Map<Long, Message> messages = new ConcurrentHashMap<>();
479	    private long nextMessageId = 1;
480	
481	    public void save(Message message) {
482	        Message messageWithId = new Message(nextMessageId++, message.getChannel(), message.getTo(), message.getSubject(), message.getBody());
483	        messages.put(messageWithId.getId(), messageWithId);
484	    }
485	
486	    public List<Message> getAll() {
487	        return messages.values().stream()
488	                .sorted(Comparator.comparingLong(Message::getId))
489	                .toList();
490	    }
491	
492	    public Message getById(long id) {
493	        return messages.get(id);
494	    }
495	}

