245	package br.com.pousada.marealta.service;
246	
247	import br.com.pousada.marealta.model.*;
248	import br.com.pousada.marealta.util.DateUtil;
249	import br.com.pousada.marealta.util.MoneyUtil;
250	import java.time.LocalDate;
251	import java.util.*;
252	import java.util.concurrent.ConcurrentHashMap;
253	
254	public class ReservationService {
255	    private final Map<Integer, Room> rooms = new ConcurrentHashMap<>();
256	    private final Map<Long, Reservation> reservations = new ConcurrentHashMap<>();
257	    private long nextReservationId = 1;
258	    private final NotificationService notificationService;
259	
260	    public ReservationService(NotificationService notificationService) {
261	        this.notificationService = notificationService;
262	        initializeRooms();
263	    }
264	
265	    private void initializeRooms() {
266	        rooms.put(101, Room.from(101, RoomType.STANDARD));
267	        rooms.put(102, Room.from(102, RoomType.STANDARD));
268	        rooms.put(201, Room.from(201, RoomType.DELUXE));
269	        rooms.put(202, Room.from(202, RoomType.DELUXE));
270	        rooms.put(301, Room.from(301, RoomType.SUITE));
271	    }
272	
273	    public List<Room> getRooms() {
274	        return rooms.values().stream()
275	                .sorted(Comparator.comparingInt(Room::number))
276	                .toList();
277	    }
278	
279	    public Room getRoom(int roomNumber) {
280	        return rooms.get(roomNumber);
281	    }
282	
283	    public Reservation createReservation(
284	            int roomNumber,
285	            String guestName,
286	            String guestEmail,
287	            String guestCpf,
288	            LocalDate checkIn,
289	            LocalDate checkOut,
290	            int guests,
291	            RatePlan ratePlan
292	    ) {
293	        Room room = rooms.get(roomNumber);
294	        if (room == null) {
295	            throw new IllegalArgumentException("ROOM_NOT_FOUND");
296	        }
297	
298	        if (guests < 1) {
299	            throw new IllegalArgumentException("INVALID_REQUEST");
300	        }
301	
302	        if (guests > room.capacity()) {
303	            throw new IllegalArgumentException("CAPACITY_EXCEEDED");
304	        }
305	
306	        if (!checkOut.isAfter(checkIn)) {
307	            throw new IllegalArgumentException("INVALID_REQUEST");
308	        }
309	
310	        if (isRoomUnavailable(roomNumber, checkIn, checkOut)) {
311	            throw new IllegalArgumentException("ROOM_UNAVAILABLE");
312	        }
313	
314	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
315	        double subtotal = 0;
316	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
317	            boolean isHighSeason = DateUtil.isHighSeason(date);
318	            double nightlyRate = MoneyUtil.calculateNightlyRate(room.nightlyRate(), isHighSeason);
319	            subtotal += nightlyRate;
320	        }
321	        subtotal = MoneyUtil.round(subtotal);
322	
323	        double discount = MoneyUtil.calculateDiscount(subtotal, ratePlan == RatePlan.NON_REFUNDABLE);
324	        double total = MoneyUtil.calculateTotal(subtotal, discount);
325	
326	        Reservation reservation = new Reservation(
327	                nextReservationId++,
328	                roomNumber,
329	                guestName,
330	                guestEmail,
331	                guestCpf,
332	                checkIn,
333	                checkOut,
334	                guests,
335	                ratePlan,
336	                nights,
337	                subtotal,
338	                discount,
339	                total
340	        );
341	
342	        reservations.put(reservation.getId(), reservation);
343	        return reservation;
344	    }
345	
346	    public Reservation getReservation(long id) {
347	        Reservation reservation = reservations.get(id);
348	        if (reservation == null) {
349	            throw new IllegalArgumentException("RESERVATION_NOT_FOUND");
350	        }
351	        return reservation;
352	    }
353	
354	    public Reservation confirm(long id, double amountPaid) {
355	        Reservation reservation = getReservation(id);
356	
357	        if (reservation.getStatus() != ReservationStatus.PENDING) {
358	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
359	        }
360	
361	        reservation.confirm(amountPaid);
362	        notificationService.notifyReservationConfirmed(reservation, rooms.get(reservation.getRoomNumber()).type());
363	        return reservation;
364	    }
365	
366	    public Reservation checkIn(long id) {
367	        Reservation reservation = getReservation(id);
368	
369	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
370	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
371	        }
372	
373	        reservation.checkIn();
374	        return reservation;
375	    }
376	
377	    public Reservation checkOut(long id) {
378	        Reservation reservation = getReservation(id);
379	
380	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
381	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
382	        }
383	
384	        reservation.checkOut();
385	        return reservation;
386	    }
387	
388	    public Reservation cancel(long id) {
389	        Reservation reservation = getReservation(id);
390	
391	        if (reservation.getStatus() != ReservationStatus.PENDING &&
392	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
393	            throw new IllegalArgumentException("OPERATION_NOT_ALLOWED");
394	        }
395	
396	        Double refundAmount = null;
397	        if (reservation.getStatus() == ReservationStatus.CONFIRMED) {
398	            if (reservation.getRatePlan() == RatePlan.STANDARD) {
399	                refundAmount = reservation.getAmountPaid();
400	            } else {
401	                refundAmount = 0.0;
402	            }
403	            notificationService.notifyReservationCancelled(reservation, rooms.get(reservation.getRoomNumber()).type(), refundAmount);
404	        }
405	
406	        reservation.cancel(refundAmount);
407	        return reservation;
408	    }
409	
410	    private boolean isRoomUnavailable(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
411	        for (Reservation res : reservations.values()) {
412	            if (res.getRoomNumber() != roomNumber) {
413	                continue;
414	            }
415	
416	            if (res.getStatus() == ReservationStatus.CANCELLED) {
417	                continue;
418	            }
419	
420	            for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
421	                if (!date.isBefore(res.getCheckIn()) && date.isBefore(res.getCheckOut())) {
422	                    return true;
423	                }
424	            }
425	        }
426	        return false;
427	    }
428	
429	    public Collection<Reservation> getAllReservations() {
430	        return reservations.values();
431	    }
432	}
