     9	    private static final DateTimeFormatter API_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    10	
    11	    public static boolean isHighSeason(LocalDate date) {
    12	        Month month = date.getMonth();
    13	        int dayOfMonth = date.getDayOfMonth();
    14	
    15	        if (month == Month.JULY) {
    16	            return true;
    17	        }
    18	
    19	        if (month == Month.DECEMBER) {
    20	            return dayOfMonth >= 15;
    21	        }
    22	
    23	        if (month == Month.JANUARY || month == Month.FEBRUARY) {
    24	            return true;
    25	        }
    26	
    27	        return false;
    28	    }
    29	
    30	    public static String format(LocalDate date) {
    31	        return date.format(FORMATTER);
    32	    }
    33	
    34	    public static String formatForApi(LocalDate date) {
    35	        return date.format(API_FORMATTER);
    36	    }
