     3	import br.com.pousada.marealta.api.dto.ErrorResponse;
     4	import io.javalin.Javalin;
     5	
     6	public class ApiErrorHandler {
     7	    public static void register(Javalin app) {
     8	        app.exception(IllegalArgumentException.class, (e, ctx) -> {
     9	            String errorCode = e.getMessage();
    10	
    11	            int status;
    12	            String message;
    13	
    14	            switch (errorCode) {
    15	                case "INVALID_REQUEST":
    16	                    status = 400;
    17	                    message = "Requisição inválida";
    18	                    break;
    19	                case "ROOM_NOT_FOUND":
    20	                    status = 404;
    21	                    message = "Quarto não encontrado";
    22	                    break;
    23	                case "RESERVATION_NOT_FOUND":
    24	                    status = 404;
    25	                    message = "Reserva não encontrada";
    26	                    break;
    27	                case "ROOM_UNAVAILABLE":
    28	                    status = 409;
    29	                    message = "Quarto indisponível para as datas solicitadas";
    30	                    break;
    31	                case "CAPACITY_EXCEEDED":
    32	                    status = 422;
    33	                    message = "Número de hóspedes exceeds room capacity";
    34	                    break;
    35	                case "OPERATION_NOT_ALLOWED":
    36	                    status = 409;
    37	                    message = "Operação não permitida para o estado atual da reserva";
    38	                    break;
    39	                default:
    40	                    status = 400;
    41	                    message = "Erro ao processar requisição";
    42	                    errorCode = "INVALID_REQUEST";
    43	            }
    44	
    45	            ctx.status(status);
    46	            ctx.json(new ErrorResponse(errorCode, message));
    47	        });
    48	    }
    49	}
