     8	public class ReservationController {
     9	    private static final String RESERVATION_NOT_FOUND_MSG = "Reserva não encontrada";
    10	
    11	    public static void register(Javalin app, ReservationService reservationService) {
    12	        app.post("/reservations", ctx -> {
    13	            try {
    14	                CreateReservationRequest req = ctx.bodyAsClass(CreateReservationRequest.class);
    15	
    16	                if (req.roomNumber() == 0 || req.guestName() == null || req.guestEmail() == null ||
    17	                    req.guestCpf() == null || req.checkIn() == null || req.checkOut() == null ||
    18	                    req.ratePlan() == null) {
    19	                    throw new IllegalArgumentException("INVALID_REQUEST");
    20	                }
    21	
    22	                RatePlan ratePlan = RatePlan.valueOf(req.ratePlan());
    23	                Reservation reservation = reservationService.createReservation(
    24	                        req.roomNumber(),
    25	                        req.guestName(),
    26	                        req.guestEmail(),
    27	                        req.guestCpf(),
    28	                        req.checkIn(),
    29	                        req.checkOut(),
    30	                        req.guests(),
    31	                        ratePlan
    32	                );
    33	
    34	                ctx.status(201);
    35	                ctx.json(ReservationResponse.from(reservation));
    36	            } catch (IllegalArgumentException e) {
    37	                if ("INVALID_REQUEST".equals(e.getMessage())) {
    38	                    throw e;
    39	                }
    40	                if ("ROOM_NOT_FOUND".equals(e.getMessage())) {
    41	                    throw e;
    42	                }
    43	                if ("ROOM_UNAVAILABLE".equals(e.getMessage())) {
    44	                    throw e;
    45	                }
    46	                if ("CAPACITY_EXCEEDED".equals(e.getMessage())) {
    47	                    throw e;
    48	                }
    49	                throw new IllegalArgumentException("INVALID_REQUEST");
    50	            } catch (IllegalStateException e) {
    51	                throw new IllegalArgumentException("INVALID_REQUEST");
    52	            }
    53	        });
    54	
    55	        app.get("/reservations/{id}", ctx -> {
    56	            long id = ctx.pathParamAsClass("id", Long.class).get();
    57	            Reservation reservation = reservationService.getReservation(id);
    58	            ctx.json(ReservationResponse.from(reservation));
    59	        });
    60	
    61	        app.post("/reservations/{id}/confirmation", ctx -> {
    62	            long id = ctx.pathParamAsClass("id", Long.class).get();
    63	            ConfirmationRequest req = ctx.bodyAsClass(ConfirmationRequest.class);
    64	            Reservation reservation = reservationService.confirm(id, req.amountPaid);
    65	            ctx.json(ReservationResponse.from(reservation));
    66	        });
    67	
    68	        app.post("/reservations/{id}/check-in", ctx -> {
    69	            long id = ctx.pathParamAsClass("id", Long.class).get();
    70	            Reservation reservation = reservationService.checkIn(id);
    71	            ctx.json(ReservationResponse.from(reservation));
    72	        });
    73	
    74	        app.post("/reservations/{id}/check-out", ctx -> {
    75	            long id = ctx.pathParamAsClass("id", Long.class).get();
    76	            Reservation reservation = reservationService.checkOut(id);
    77	            Room room = reservationService.getRoom(reservation.getRoomNumber());
    78	            ReservationDocument document = ReservationDocument.from(reservation, room.type());
    79	            ctx.json(ReservationDocumentResponse.from(document));
    80	        });
    81	
    82	        app.post("/reservations/{id}/cancellation", ctx -> {
    83	            long id = ctx.pathParamAsClass("id", Long.class).get();
    84	            Reservation reservation = reservationService.cancel(id);
    85	            ctx.json(ReservationResponse.from(reservation));
    86	        });
    87	
    88	        app.get("/reservations/{id}/document", ctx -> {
    89	            long id = ctx.pathParamAsClass("id", Long.class).get();
    90	            Reservation reservation = reservationService.getReservation(id);
    91	
    92	            if (reservation.getStatus() != ReservationStatus.CONFIRMED &&
    93	                reservation.getStatus() != ReservationStatus.CHECKED_IN &&
    94	                reservation.getStatus() != ReservationStatus.CHECKED_OUT) {
    95	                ctx.status(404);
    96	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", RESERVATION_NOT_FOUND_MSG));
    97	                return;
    98	            }
    99	
   100	            Room room = reservationService.getRoom(reservation.getRoomNumber());
   101	            ReservationDocument document = ReservationDocument.from(reservation, room.type());
   102	            ctx.json(ReservationDocumentResponse.from(document));
   103	        });
   104	    }
   105	
   106	    record ConfirmationRequest(double amountPaid) {}
   107	}
