     1	package br.com.pousada.marealta.service;
     2	
     3	import br.com.pousada.marealta.model.*;
     4	import br.com.pousada.marealta.util.DateUtil;
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	import java.util.*;
     8	
     9	public class ReportService {
    10	    private final ReservationService reservationService;
    11	
    12	    public ReportService(ReservationService reservationService) {
    13	        this.reservationService = reservationService;
    14	    }
    15	
    16	    public String getOccupancyReport(LocalDate date) {
    17	        StringBuilder csv = new StringBuilder();
    18	        csv.append("room,type,reservation,check_in,check_out\n");
    19	
    20	        List<Reservation> occupiedReservations = new ArrayList<>();
    21	        for (Reservation res : reservationService.getAllReservations()) {
    22	            if (res.getStatus() == ReservationStatus.CANCELLED) {
    23	                continue;
    24	            }
    25	            if (res.getStatus() == ReservationStatus.PENDING) {
    26	                continue;
    27	            }
    28	
    29	            LocalDate checkInDate = res.getCheckIn();
    30	            LocalDate checkOutDate = res.getCheckOut();
    31	
    32	            if (!date.isBefore(checkInDate) && date.isBefore(checkOutDate)) {
    33	                occupiedReservations.add(res);
    34	            }
    35	        }
    36	
    37	        occupiedReservations.sort(Comparator.comparingInt(Reservation::getRoomNumber)
    38	                .thenComparingLong(Reservation::getId));
    39	
    40	        for (Reservation res : occupiedReservations) {
    41	            Room room = reservationService.getRoom(res.getRoomNumber());
    42	            csv.append(res.getRoomNumber()).append(",")
    43	                    .append(room.type().getDisplayName()).append(",")
    44	                    .append(res.getId()).append(",")
    45	                    .append(DateUtil.formatForApi(res.getCheckIn())).append(",")
    46	                    .append(DateUtil.formatForApi(res.getCheckOut())).append("\n");
    47	        }
    48	
    49	        csv.append("total,").append(occupiedReservations.size()).append("/5\n");
    50	        return csv.toString();
    51	    }
    52	
    53	    public String getRevenueReport(YearMonth month) {
    54	        StringBuilder csv = new StringBuilder();
    55	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    56	
    57	        List<Reservation> monthReservations = new ArrayList<>();
    58	        for (Reservation res : reservationService.getAllReservations()) {
    59	            LocalDate checkInMonth = res.getCheckIn();
    60	            if (YearMonth.from(checkInMonth).equals(month)) {
    61	                if (isMoneyReceivedOrRefunded(res)) {
    62	                    monthReservations.add(res);
    63	                }
    64	            }
    65	        }
    66	
    67	        monthReservations.sort(Comparator.comparing(Reservation::getCheckIn)
    68	                .thenComparingLong(Reservation::getId));
    69	
    70	        double totalAmount = 0;
    71	        for (Reservation res : monthReservations) {
    72	            double amount = res.getAmountPaid();
    73	            if (res.getRefund() != null) {
    74	                amount -= res.getRefund();
