     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	
     6	public class MoneyUtil {
     7	    private static final BigDecimal DISCOUNT_PERCENTAGE = new BigDecimal("0.15");
     8	
     9	    public static double round(double value) {
    10	        return new BigDecimal(value)
    11	                .setScale(2, RoundingMode.HALF_EVEN)
    12	                .doubleValue();
    13	    }
    14	
    15	    public static double calculateNightlyRate(double baseRate, boolean isHighSeason) {
    16	        double rate = baseRate;
    17	        if (isHighSeason) {
    18	            rate = rate * 1.20;
    19	        }
    20	        return round(rate);
    21	    }
    22	
    23	    public static double calculateSubtotal(double nightlyRate, int nights) {
    24	        double subtotal = nightlyRate * nights;
    25	        return round(subtotal);
    26	    }
    27	
    28	    public static double calculateDiscount(double subtotal, boolean isNonRefundable) {
    29	        if (!isNonRefundable) {
    30	            return 0;
    31	        }
    32	        BigDecimal discount = new BigDecimal(subtotal).multiply(DISCOUNT_PERCENTAGE);
    33	        return round(discount.doubleValue());
    34	    }
    35	
    36	    public static double calculateTotal(double subtotal, double discount) {
    37	        double total = subtotal - discount;
    38	        return round(total);
    39	    }
    40	}
